INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-CC9AAEAE634AB3A85F07','research',NULL,'The Centre for Linguistic and Historical Studies by Oral Tradition (CELHTO) | African Union','https://au.int/en/centre-linguistic-and-historical-studies-oral-tradition-celhto',NULL,'African Union Specialized Agencies',NULL,'African Union','Africa','intergovernmental_directory','2023-05-25T08:11:00Z',NULL,'2026-10-03T22:48:17.715Z','institutional_primary','en','The Centre for Linguistic and Historical Studies by Oral Tradition (CELHTO) is a specialised technical agency of the African Union and aims to contribute to Africa’s integration and development by providing analysis on African history, societies and culture. Its main mandate is to work for the recovery of the continent’s autonomy from external cultural visions by affirming a cultural identity that promotes the integration and development of the continent.','The Centre for Linguistic and Historical Studies by Oral Tradition (CELHTO) is a specialised technical agency of the African Union and aims to contribute to Africa’s integration and development by providing analysis on African history, societies and culture. Its main mandate is to work for the recovery of the continent’s autonomy from external cultural visions by affirming a cultural identity that promotes the integration and development of the continent.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://au.int/en/centre-linguistic-and-historical-studies-oral-tradition-celhto',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','6c569c95647584c7e8d5a7de9b3f40797adf634757989971de36a0bad095b901','cc9aaeae634ab3a85f075863614e231416b3e5799eb94c75d0ca65a33f4f45cf',1,1,1,1 FROM sources WHERE root_url='https://au.int/en/specialised-agencies-institutions' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
