INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-E03A69AA45F5AAC15B33','research',NULL,'Applied Astronomy Group----Yunnan Observatories','https://english.ynao.cas.cn/research/rg/aarg/',NULL,'*Yunnan Observatories',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T22:48:20.038Z','institutional_primary','en','The Applied Astronomy Group of Yunnan Observatories has developed, and is currently operating, the following instruments: the 1.2m telescope, the 1.8m telescope, the space debris telescope, the small photoelectric telescope, CAPS, and three GPS calibration stations.','The Applied Astronomy Group of Yunnan Observatories has developed, and is currently operating, the following instruments: the 1.2m telescope, the 1.8m telescope, the space debris telescope, the small photoelectric telescope, CAPS, and three GPS calibration stations.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.ynao.cas.cn/research/rg/aarg/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','75fb949a89c913b146fb5e81671c8c464bc248032525ad02997b9883f23a29c3','e03a69aa45f5aac15b334812c4668ac0546fe28a0501690848a0c771f6553702',1,1,1,1 FROM sources WHERE root_url='https://english.ynao.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excl