INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-ADDBADAF5D928063C144','research',NULL,'Astrometry and Application Group----Yunnan Observatories','https://english.ynao.cas.cn/research/rg/aag/',NULL,'*Yunnan Observatories',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T22:48:20.039Z','institutional_primary','en','The Astrometry & Application Group is the successor of the former Astrometry Laboratory of Yunnan Observatories, the succession having taken place in 2009. The group currently employs 8 personnel, and is headed by Yunnan Observatories Professor Jiancheng Wang.','The Astrometry & Application Group is the successor of the former Astrometry Laboratory of Yunnan Observatories, the succession having taken place in 2009. The group currently employs 8 personnel, and is headed by Yunnan Observatories Professor Jiancheng Wang.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.ynao.cas.cn/research/rg/aag/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e27fb2baf55d64914405af4f9cb78754f7e8246c8345a1eb2d5b435e291ecbd2','addbadaf5d928063c144c63d9c67b258e6cbf74dee55b73d92cd6156d9cd39e1',1,1,1,1 FROM sources WHERE root_url='https://english.ynao.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.