INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-052822D17048D69F2B7B','research',NULL,'Radio Astronomy Group----Yunnan Observatories','https://english.ynao.cas.cn/research/rg/rag/',NULL,'*Yunnan Observatories',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T22:48:21.138Z','institutional_primary','en','The Radio Astronomy Group is an important component of Yunnan Observatories. It is in charge of the 40m Radio Telescope, the second largest in China, as well as a 10m radio telescope for solar observation purposes. It is also responsible for maintaining the functions of the 40m Radio Telescope in the national VLBI project and the national space programs.','The Radio Astronomy Group is an important component of Yunnan Observatories. It is in charge of the 40m Radio Telescope, the second largest in China, as well as a 10m radio telescope for solar observation purposes. It is also responsible for maintaining the functions of the 40m Radio Telescope in the national VLBI project and the national space programs.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.ynao.cas.cn/research/rg/rag/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','84f301f7a5c940ea126132e86a716c99ce7d36061405cf256770ab9f096ca5ce','052822d17048d69f