INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-BEBCCCDDC36F0E75BFE6','research',NULL,'State Key Laboratory of Functional Crystals and Devices--Shanghai Institute of Ceramics, Chinese Academy of Sciences','https://english.sic.cas.cn/rh/fcd/',NULL,'Shanghai Institute of Ceramics',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T22:51:02.933Z','institutional_primary','en','In order to promote the development of functional crystals and devices in China and expand the country''s international influence in this field, the Chinese Academy of Sciences approved the establishment of the "Key Laboratory of Functional Crystals and Devices" by the Shanghai Institute of Ceramics and the Fujian Institute of Research on the Structure of Matter in November 2024. In January 2025, following an evaluation by the Ministry of Science and Technology, the National Key Laboratory of Functional Crystals and Devices was approved for construction.','In order to promote the development of functional crystals and devices in China and expand the country''s international influence in this field, the Chinese Academy of Sciences approved the establishment of the "Key Laboratory of Functional Crystals and Devices" by the Shanghai Institute of Ceramics and the Fujian Institute of Research on the Structure of Matter in November 2024. In January 2025, following an evaluation by the Ministry of Science and Technology, the National Key Laboratory of Functional Crystals and Devices was approved for construction.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.sic.cas.cn/rh/fcd/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','21d6da891fd7766e9f97e76f2564f707cad37f0c69623d3f9444fdd105031262','bebcccddc36f0e75bfe67aa7eee21bcd028b36ce17d771fe7d02e6d4dfe30918',1,1,1,1 FROM sources WHERE root_url='https://english.sic.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-1D6A2E44659CCE039361','research',NULL,'State Key Laboratory of High Performance Ceramics--Shanghai Institute of Ceramics, Chinese Academy of Sciences','https://english.sic.cas.cn/rh/hpc/',NULL,'Shanghai Institute of Ceramics',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T22:51:03.047Z','institutional_primary','en','The State Key Laboratory of High Performance Ceramics and Superfine Microstructure was founded in April 1988 upon the approval of both the State Planning Commission and the Chinese Academy of Sciences, aiming at promoting the high-performance ceramic research activity in China. The laboratory is subject to the Shanghai Institute of Ceramics, Chinese Academy of Sciences, and has been open to all over the world since 1989. In 1991, the laboratory formerly became one of the State Key Laboratories and has been given the name since then. In January 2023, the Chinese Academy of Sciences approved the reorganization of the laboratory as the “State Key Laboratory of High Performance Ceramics”. In January 2025, it passed the reorganization evaluation by the Ministry of Science and Technology and was officially established.','The State Key Laboratory of High Performance Ceramics and Superfine Microstructure was founded in April 1988 upon the approval of both the State Planning Commission and the Chinese Academy of Sciences, aiming at promoting the high-performance ceramic research activity in China. The laboratory is subject to the Shanghai Institute of Ceramics, Chinese Academy of Sciences, and has been open to all over the world since 1989. In 1991, the laboratory formerly became one of the State Key Laboratories and has been given the name since then. In January 2023, the Chinese Academy of Sciences approved the reorganization of the laboratory as the “State Key Laboratory of High Performance Ceramics”. In January 2025, it passed the reorganization evaluation by the Ministry of Science and Technology and was officially established.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.sic.cas.cn/rh/hpc/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','3db07e68333bdbc57409adb34b3c33d2303a59345c23b4fbccd76cba37a2821b','1d6a2e44659cce0393613e29dcfd8a122478a749dd33b48e1a716bc30dc84fd5',1,1,1,1 FROM sources WHERE root_url='https://english.sic.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-C6BE177C9F783E0BD965','research',NULL,'Structural Ceramics and Composite Materials--Shanghai Institute of Ceramics, Chinese Academy of Sciences','https://english.sic.cas.cn/rh/r2/',NULL,'Shanghai Institute of Ceramics',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T22:51:03.303Z','institutional_primary','en','Center of Structural Ceramics and Composite Materials is mainly engaged in basic research, applied basic research and high-tech product development of advanced structural ceramics and ceramic matrix composite materials. In the face of major national strategic needs such as aerospace and semiconductors, basing on the research of new principles, new structures, and new methods of structural ceramics and ceramic matrix composite materials, we are focusing on the design, preparation science, and performance evaluation and engineering applied technology research of large-size complex-shape structural ceramics and ceramic matrix composite materials. There are currently 4 research groups and 86 scientific researchers and engineers.','Center of Structural Ceramics and Composite Materials is mainly engaged in basic research, applied basic research and high-tech product development of advanced structural ceramics and ceramic matrix composite materials. In the face of major national strategic needs such as aerospace and semiconductors, basing on the research of new principles, new structures, and new methods of structural ceramics and ceramic matrix composite materials, we are focusing on the design, preparation science, and performance evaluation and engineering applied technology research of large-size complex-shape structural ceramics and ceramic matrix composite materials. There are currently 4 research groups and 86 scientific researchers and engineers.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://english.sic.cas.cn/rh/r2/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','eaf2314c3c06c6c2560967ebe2c209be626ab77ab05e4f920215910a7d0edf37','c6be177c9f783e0bd965da4740f13e23cabec0c9e6d89b9b07904190fe3d6516',1,1,1,1 FROM sources WHERE root_url='https://english.sic.cas.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-A8CFD7F22868508A7B46','research',NULL,'Research-University of Science and Technology of China','https://en.ustc.edu.cn/Research.htm',NULL,'University of Science and Technology of China',NULL,'China','Asia','official_research_institution',NULL,NULL,'2026-10-03T22:51:15.083Z','institutional_primary','en','At a lab of the University of Science and Technology of China (USTC), AI and automation have transformed traditional chemistry research from manual trial-and-error to giving instructions on intelligent platforms. In 2021, Professor Jiang Jun''s team developed the first-generation robotic chemist "Xiao Lai," enabling 24/7 operation and autonomous experiment design. The second-generation "Xiao Lin" now handles more complex tasks, evolving from a labor substitute to a collaborative research partner. The team''s ultimate goal is fully autonomous science, where machines can discover new research directions and assist even non-experts in material creation. (Xinhua)','At a lab of the University of Science and Technology of China (USTC), AI and automation have transformed traditional chemistry research from manual trial-and-error to giving instructions on intelligent platforms. In 2021, Professor Jiang Jun''s team developed the first-generation robotic chemist "Xiao Lai," enabling 24/7 operation and autonomous experiment design. The second-generation "Xiao Lin" now handles more complex tasks, evolving from a labor substitute to a collaborative research partner. The team''s ultimate goal is fully autonomous science, where machines can discover new research directions and assist even non-experts in material creation. (Xinhua)',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://en.ustc.edu.cn/Research.htm',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','43488f9a2584dd0ed0b567e6ac4310e3322f82bfbbcdad7cfc5a605617a6417d','a8cfd7f22868508a7b46722c9df550a88c6f1f617e039a3a1396d4a529915137',1,1,1,1 FROM sources WHERE root_url='https://en.ustc.edu.cn/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
