INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-619EBE7946E43DC7949A','research',NULL,'Advanced General Intelligence for Science Program (AGIS) | RIKEN','https://www.riken.jp/en/research/labs/trip/agis/',NULL,'RIKEN',NULL,'Japan','Asia','public_research',NULL,NULL,'2026-10-03T22:50:43.895Z','institutional_primary','en','AGIS program will introduce the technology of generative AI and will develop foundation models and AI agents for scientific research to further accelerate the research cycle, as well as strengthen activities to lead advanced science to social impact.','AGIS program will introduce the technology of generative AI and will develop foundation models and AI agents for scientific research to further accelerate the research cycle, as well as strengthen activities to lead advanced science to social impact.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.riken.jp/en/research/labs/trip/agis/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','0df00b62f50df7b9e7b74354df13015820aae04de1a6b76a3ae1ddbd74acec40','619ebe7946e43dc7949a68ede858e40dae10252437b4e04e16ce3729184b3d60',1,1,1,1 FROM sources WHERE root_url='https://www.riken.jp/en/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http