INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-70BECD494985D374786D','research',NULL,'Advanced Semiconductor Science Program (ASSP) | RIKEN','https://www.riken.jp/en/research/labs/trip/assp/',NULL,'RIKEN',NULL,'Japan','Asia','public_research',NULL,NULL,'2026-10-03T22:50:43.894Z','institutional_primary','en','As the technology for generative AI develops and its use expands dramatically, reducing energy consumption has become an urgent issue. In order to achieve ultra-low power consumption for AI servers, technological innovation is required for the semiconductor devices used in generative AI. The Advanced Semiconductor Science Program (ASSP) promotes the design and development of semiconductor devices that can be used in next-generation supercomputing infrastructures, integrated device for advanced computational science, and the foundation for new science, such as quantum innovation, in collaboration with various research centers within RIKEN. In addition, we aim to reduce the cost of design and apply it to edge AI through collaboration with universities and companies in Japan and overseas.','As the technology for generative AI develops and its use expands dramatically, reducing energy consumption has become an urgent issue. In order to achieve ultra-low power consumption for AI servers, technological innovation is required for the semiconductor devices used in generative AI. The Advanced Semiconductor Science Program (ASSP) promotes the design and development of semiconductor devices that can be used in next-generation supercomputing infrastructures, integrated device for advanced computational science, and the foundation for new science, such as quantum innovation, in collaboration with various research centers within RIKEN. In addition, we aim to reduce the cost of design and apply it to edge AI through collaboration with universities and companies in Japan and overseas.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.riken.jp/en/research/labs/trip/assp/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','34bbf914e445b30dee31600b18d01edc13db3ddcb733b6591b882a44baa13a58','70becd494985d374786d535d876942cee2c28f96bbb375a08fa8f9c52e1831ad',1,1,1,1 FROM sources WHERE root_url='https://www.riken.jp/en/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-F873A419073BB8DF21A5','research',NULL,'Data and Computational Sciences Integration Research Program (CoRe) | RIKEN','https://www.riken.jp/en/research/labs/trip/core/',NULL,'RIKEN',NULL,'Japan','Asia','public_research',NULL,NULL,'2026-10-03T22:50:43.418Z','institutional_primary','en','CoRe is a program carrying out research and development on the following themes: Construction and upgrading of a quantum-supercomputer hybrid platform; Development of a high-quality data storage and data use environment; Advanced simulation methods to make the best use of such data; Collaboration between data science and computational science and prediction algorithm development. We are expanding computationally viable regions and pioneering the science of predictive control in the future. The results of this research will be pioneeringly used for problems in diverse research fields, such as physics, chemistry, and life science. This program will find new scientific horizons and clues to solving global-scale issues, thereby opening up pathways of knowledge toward a better future.','CoRe is a program carrying out research and development on the following themes: Construction and upgrading of a quantum-supercomputer hybrid platform; Development of a high-quality data storage and data use environment; Advanced simulation methods to make the best use of such data; Collaboration between data science and computational science and prediction algorithm development. We are expanding computationally viable regions and pioneering the science of predictive control in the future. The results of this research will be pioneeringly used for problems in diverse research fields, such as physics, chemistry, and life science. This program will find new scientific horizons and clues to solving global-scale issues, thereby opening up pathways of knowledge toward a better future.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.riken.jp/en/research/labs/trip/core/',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','6c7c7453ca60e8884faf8b68d24ee0136c31d00d7751331a28a42b5f689f4e4d','f873a419073bb8df21a53ad67a6a0ce6d653bebeb36d0c3d41d1e8b1e0495b79',1,1,1,1 FROM sources WHERE root_url='https://www.riken.jp/en/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-5D013E91AA618409F493','research',NULL,'ECL Unit Leader Leo Speidel elected a 2026 AYS Fellow in Life Sciences | RIKEN','https://www.riken.jp/en/news_pubs/news/2026/20260907_1/index.html',NULL,'RIKEN',NULL,'Japan','Asia','public_research',NULL,NULL,'2026-10-03T22:50:44.208Z','institutional_primary','en','Leo Speidel, a RIKEN ECL Unit Leader at the RIKEN Center for Interdisciplinary Theoretical and Mathematical Sciences (iTHEMS) and RIKEN Pioneering Research Institute(PRI) , has been elected as a 2026 Asian Young Scientist (AYS) Fellow in Life Sciences. AYSF is a privately funded research fellowship that aims to encourage and support young scientists in Asia to carry out creative and transformative research. The Fellowship annually selects early-career scientists in three fundamental disciplines: 1) Life Science, 2) Physical Science, and 3) Mathematics and Computer Science. Speidel’s research focuses on the development and application of new mathematical and statistical techniques to reveal human evolution, with the goal of reconstructing genome-wide genealogies across individuals and species. He was selected for this year’s AYSF in recognition of his pioneering achievements.','Leo Speidel, a RIKEN ECL Unit Leader at the RIKEN Center for Interdisciplinary Theoretical and Mathematical Sciences (iTHEMS) and RIKEN Pioneering Research Institute(PRI) , has been elected as a 2026 Asian Young Scientist (AYS) Fellow in Life Sciences. AYSF is a privately funded research fellowship that aims to encourage and support young scientists in Asia to carry out creative and transformative research. The Fellowship annually selects early-career scientists in three fundamental disciplines: 1) Life Science, 2) Physical Science, and 3) Mathematics and Computer Science. Speidel’s research focuses on the development and application of new mathematical and statistical techniques to reveal human evolution, with the goal of reconstructing genome-wide genealogies across individuals and species. He was selected for this year’s AYSF in recognition of his pioneering achievements.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.riken.jp/en/news_pubs/news/2026/20260907_1/index.html',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','14b286b135b263aa4042b5331295e7aff38bba978e91db3cd497b9f462cf66ad','5d013e91aa618409f4936cc7307cc46f67f265ed699d5342543ba3eba7d0760c',1,1,1,1 FROM sources WHERE root_url='https://www.riken.jp/en/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-1C659255994C1BCA1686','research',NULL,'Fundamental Quantum Science Program (FQSP) | RIKEN','https://www.riken.jp/en/research/labs/trip/fqsp/',NULL,'RIKEN',NULL,'Japan','Asia','public_research',NULL,NULL,'2026-10-03T22:50:43.831Z','institutional_primary','en','Although quantum science and technology are advancing rapidly, we still lack a deep understanding of their basic principles. Our Fundamental Quantum Science Program focuses on four key areas—basic physics and chemistry, mathematics, quantum information, and nonequilibrium science—returning to the foundations of quantum science and advancing research from a mid- to long-term perspective.','Although quantum science and technology are advancing rapidly, we still lack a deep understanding of their basic principles. Our Fundamental Quantum Science Program focuses on four key areas—basic physics and chemistry, mathematics, quantum information, and nonequilibrium science—returning to the foundations of quantum science and advancing research from a mid- to long-term perspective.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.riken.jp/en/research/labs/trip/fqsp/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','6c11ff2445e1fb811b0eb23179af901683