INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-2C7487AD17238B4EDD5C','research',NULL,'RIKEN and Argonne National Laboratory sign MOU on AI for Science | RIKEN','https://www.riken.jp/en/news_pubs/news/2024/20240411_1/',NULL,'RIKEN',NULL,'Japan','Asia','public_research',NULL,NULL,'2026-10-03T22:50:43.305Z','institutional_primary','en','In the United States-Japan Joint Leaders’ Statement released today, the collaboration between RIKEN and Argonne National Laboratory on AI for Science was welcomed.','In the United States-Japan Joint Leaders’ Statement released today, the collaboration between RIKEN and Argonne National Laboratory on AI for Science was welcomed.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.riken.jp/en/news_pubs/news/2024/20240411_1/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','d2f52660d507ae99217e863489617a623d8e028266f59efeab7703633c6dfba1','2c7487ad17238b4edd5c03eb680a5bf9af45ad12fabf488198b46f485ef6755c',1,1,1,1 FROM sources WHERE root_url='https://www.riken.jp/en/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-9E6197E0776D359A4C03','research',NULL,'RIKEN Center for Sustainable Resource Science | RIKEN','https://www.riken.jp/en/research/labs/csrs/',NULL,'RIKEN',NULL,'Japan','Asia','public_research',NULL,NULL,'2026-10-03T22:50:43.163Z','institutional_primary','en','Human activities are rapidly pushing the resilience and stability that the Earth system naturally possesses to its limits. To contribute to the harmony between human activities and the Earth system, the Center for Sustainable Resource Science (CSRS) is promoting four strategic programs: ''Sustainable Bioproduction'', ''Material Circulation and Catalysis'', ''Symbiosis and Environment'', and ''Advanced Research and Technology Platforms''. CSRS is advancing the development of stress-resistant plants and environmentally friendly crop production technologies, and is engaged in manufacturing that utilizes the power of organisms and catalysts. By collaborating with researchers in the computational science and the prediction science, as well as experts from the humanities and social sciences fields, CSRS aims to bring the achievements of fundamental science to society. Through the power of science, CSR','Human activities are rapidly pushing the resilience and stability that the Earth system naturally possesses to its limits. To contribute to the harmony between human activities and the Earth system, the Center for Sustainable Resource Science (CSRS) is promoting four strategic programs: ''Sustainable Bioproduction'', ''Material Circulation and Catalysis'', ''Symbiosis and Environment'', and ''Advanced Research and Technology Platforms''. CSRS is advancing the development of stress-resistant plants and environmentally friendly crop production technologies, and is engaged in manufacturing that utilizes the power of organisms and catalysts. By collaborating with researchers in the computational science and the prediction science, as well as experts from the humanities and social sciences fields, CSRS aims to bring the achievements of fundamental science to society. Through the power of science, CSR',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.riken.jp/en/research/labs/csrs/',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','fdeb1632fcecaa1ce9c612e5c0c58f8dc269308b04243ced89f7b19f88fb698c','9e6197e0776d359a4c03a8e847583d326dc85c094e78b0feb926d12bf26ad035',1,1,1,1 FROM sources WHERE root_url='https://www.riken.jp/en/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-755A8BF97FF4B5A50B1C','research',NULL,'RIKEN establishes innovation company | RIKEN','https://www.riken.jp/en/news_pubs/news/2019/20191217_3/',NULL,'RIKEN',NULL,'Japan','Asia','public_research',NULL,NULL,'2026-10-03T22:50:43.910Z','institutional_primary','en','On September 5, RIKEN established a fully-owned subsidiary, RIKEN Innovation, Co., Ltd., which will work to improve communication between private industry and RIKEN, and to support collaborative projects. This move was made possible by a new law passed in January of this year which allows National Research and Development Institutes such as RIKEN to establish subsidiaries to carry out work related to licensing technologies and conducting joint research with the private sector. Starting on December 1, the new company began carrying out business on behalf of RIKEN. Simultaneously, RIKEN''s Cluster for Innovation, which previously handled such work, was shut down.','On September 5, RIKEN established a fully-owned subsidiary, RIKEN Innovation, Co., Ltd., which will work to improve communication between private industry and RIKEN, and to support collaborative projects. This move was made possible by a new law passed in January of this year which allows National Research and Development Institutes such as RIKEN to establish subsidiaries to carry out work related to licensing technologies and conducting joint research with the private sector. Starting on December 1, the new company began carrying out business on behalf of RIKEN. Simultaneously, RIKEN''s Cluster for Innovation, which previously handled such work, was shut down.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.riken.jp/en/news_pubs/news/2019/20191217_3/',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','c6a96ac8bc3033672c23c83679f284ecf09f86afc5d36261cd661091c2028b93','755a8bf97ff4b5a50b1c53b33b71c5f93d6f36c5e26e1c431ad0d95c37493f5e',1,1,1,1 FROM sources WHERE root_url='https://www.riken.jp/en/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
