INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-08818FD6FBA1ECD77544','research',NULL,'Korea Institutes of Science and Technology Information (KISTI) - NST 영문 홈페이지','https://www.nst.re.kr/eng/contents.do?key=323',NULL,'National Research Council of Science & Technology',NULL,'South Korea','Asia','government_research_council',NULL,NULL,'2026-10-03T22:50:55.971Z','institutional_primary','en','The Korea Institute of Science and Technology Information (KISTI), founded in 1962, is a government-funded research institute advancing national science and technology through expertise in information services, artificial intelligence, and high-performance computing infrastructure. Headquartered in Daejeon, Korea’s leading science and technology hub, KISTI provides advanced services in data analytics, cybersecurity, and research networks, and operates Korea’s national supercomputers, including the 5th flagship system Nurion and the upcoming 6th-generation system.','The Korea Institute of Science and Technology Information (KISTI), founded in 1962, is a government-funded research institute advancing national science and technology through expertise in information services, artificial intelligence, and high-performance computing infrastructure. Headquartered in Daejeon, Korea’s leading science and technology hub, KISTI provides advanced services in data analytics, cybersecurity, and research networks, and operates Korea’s national supercomputers, including the 5th flagship system Nurion and the upcoming 6th-generation system.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.nst.re.kr/eng/contents.do?key=323',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','163c1ff982a1c1f49dc3aa9c26b5ec9b4aa2b70325f012b3b736ebe3f122384a','08818fd6fba1ecd77544c61de6dfb360448092ae903610b1cd660cacd0b5388f',1,1,1,1 FROM sources WHERE root_url='https://www.nst.re.kr/eng/contents.do?key=153' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
