INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-D4E9B403743CB661E78F','research_infrastructure',NULL,'Projects and Landmarks | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/projects-and-landmarks/',NULL,'Physical Sciences & Engineering / Landmark ELI ERIC Extreme Light Infrastructure',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-03T22:50:12.687Z','institutional_primary','en','ESFRI Research Infrastructures are facilities, resources or services of a unique nature, identified by European research communities to conduct and to support top-level research activities in their domains. ESFRI selects proposals of RIs in strategic areas of research and with an adequate level of maturity to become ESFRI Projects, and identifies successfully implemented RIs to become ESFRI Landmarks.','ESFRI Research Infrastructures are facilities, resources or services of a unique nature, identified by European research communities to conduct and to support top-level research activities in their domains. ESFRI selects proposals of RIs in strategic areas of research and with an adequate level of maturity to become ESFRI Projects, and identifies successfully implemented RIs to become ESFRI Landmarks.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/projects-and-landmarks/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','770e08c010e4e76b8f82bc554a0db66977d206da0d2d5b8d58c9ead1fd7645c4','d4e9b403743cb661e78fa4fcdcbfae53714514885d70dc63663a1e2d214a9169',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eli-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-64F5744E9F1CE04C5AF6','research_infrastructure',NULL,'Roadmap & Strategy report | ESFRI Roadmap 2021','https://roadmap2021.esfri.eu/strategy-report/',NULL,'Physical Sciences & Engineering / Landmark ELI ERIC Extreme Light Infrastructure',NULL,'European Research Area','Europe','official_research_infrastructure_record',NULL,NULL,'2026-10-03T22:50:12.633Z','institutional_primary','en','The European Strategy Forum on Research Infrastructures (ESFRI) In June 2001, the Research Council invited "the Commission, in close collaboration with the Member States, to explore the establishment of new arrangements to support policies related to research infrastructures”. The first meeting of ESFRI took place in Brussels on 25 April 2002. Detailed mandate and rules governing ESFRI are laid out in ESFRI Procedural Guidelines, see: www.esfri.eu , established in 2002, brings together national governments, the scientific community and the European Commission (EC) to support a coherent, strategy-led approach to Research Infrastructures (RI) in Europe.','The European Strategy Forum on Research Infrastructures (ESFRI) In June 2001, the Research Council invited "the Commission, in close collaboration with the Member States, to explore the establishment of new arrangements to support policies related to research infrastructures”. The first meeting of ESFRI took place in Brussels on 25 April 2002. Detailed mandate and rules governing ESFRI are laid out in ESFRI Procedural Guidelines, see: www.esfri.eu , established in 2002, brings together national governments, the scientific community and the European Commission (EC) to support a coherent, strategy-led approach to Research Infrastructures (RI) in Europe.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://roadmap2021.esfri.eu/strategy-report/',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e5b6513bcdab5b3507bc670f8cb1bc93bfada3713e38d26759c02e986503b12c','64f5744e9f1ce04c5af6fad15eb8b53f10a427550bf3fc4c4ff0a73e371f0381',1,1,1,1 FROM sources WHERE root_url='https://roadmap2021.esfri.eu/projects-and-landmarks/browse-the-catalogue/eli-eric/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
