INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-553AF8C8A07A4AB1A5BD','research',NULL,'Fabrique de savoirs - VivaTech 2026 : de la recherche fondamentale à l’innovation','https://www.cea.fr/drf/Pages/Actualites/Vie-de-la-DRF/2026/VivaTech-2026-de-la-recherche-fondamentale-a-l-innovation.aspx',NULL,'CEA',NULL,'France','Europe','public_research','2026-6-26',NULL,'2026-10-03T22:48:44.776Z','institutional_primary','fr','À l’occasion de la 10ᵉ édition de VivaTech, qui s’est tenue du 17 au 20 juin 2026 à Paris, le CEA a réaffirmé son ambition de faire de l’innovation technologique un levier stratégique au service de la souveraineté industrielle, scientifique et numérique. Aux côtés des autres entités du CEA, la Direction de la Recherche Fondamentale (DRF) a illustré sa capacité à transformer des avancées scientifiques de long terme en technologies de rupture et en start-up à fort potentiel.','À l’occasion de la 10ᵉ édition de VivaTech, qui s’est tenue du 17 au 20 juin 2026 à Paris, le CEA a réaffirmé son ambition de faire de l’innovation technologique un levier stratégique au service de la souveraineté industrielle, scientifique et numérique. Aux côtés des autres entités du CEA, la Direction de la Recherche Fondamentale (DRF) a illustré sa capacité à transformer des avancées scientifiques de long terme en technologies de rupture et en start-up à fort potentiel.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.cea.fr/drf/Pages/Actualites/Vie-de-la-DRF/2026/VivaTech-2026-de-la-recherche-fondamentale-a-l-innovation.aspx',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','106af2f96407e8a768327d8f116a13b67cfcae7d73cf07e188a6fcf31977d821','553af8c8a07a4ab1a5bd6c1cd83820add5c6c48db590ba9d98bc77fdf6b3d49f',1,1,1,1 FROM sources WHERE root_url='https://www.cea.fr/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-6380EBED3DEA4761A043','research',NULL,'Institut des sciences du vivant Frédéric-Joliot - Les bébés doués de conscience ?','https://www.cea.fr/drf/Pages/Actualites/En-direct-des-labos/2013/Les-bebes-doues-de-conscience-.aspx',NULL,'CEA',NULL,'France','Europe','public_research','2013-4-19',NULL,'2026-10-03T22:48:44.346Z','institutional_primary','fr','Les bébés ont longtemps été considérés comme ayant des comportements principalement automatiques qui ne s’accompagnent pas d’une expérience subjective consciente. Et pourtant : des chercheurs du CEA-I2BM et du CNRS montrent que les nourrissons possèdent dès 5 mois une forme de conscience similaire à celle des adultes.','Les bébés ont longtemps été considérés comme ayant des comportements principalement automatiques qui ne s’accompagnent pas d’une expérience subjective consciente. Et pourtant : des chercheurs du CEA-I2BM et du CNRS montrent que les nourrissons possèdent dès 5 mois une forme de conscience similaire à celle des adultes.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.cea.fr/drf/Pages/Actualites/En-direct-des-labos/2013/Les-bebes-doues-de-conscience-.aspx',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a31cc6b8abd5984d5399f6bfa17c9a00fb61aa75c75bce7c4909e16a3a5fa542','6380ebed3dea4761a043af29f6304b99fcd5d26ee5b75ee3449e219460c0f37d',1,1,1,1 FROM sources WHERE root_url='https://www.cea.fr/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-68BC9049962A25FBE082','research',NULL,'Institut des sciences du vivant Frédéric-Joliot - Les grands modèles de langage ont-ils une conscience ?','https://www.cea.fr/presse/Pages/actualites-communiques/ntic/modeles-langage-ont-ils-conscience.aspx',NULL,'CEA',NULL,'France','Europe','public_research','2026-7-27',NULL,'2026-10-03T22:48:44.314Z','institutional_primary','fr','Dans une étude publiée début juillet, l’entreprise américaine Anthropic affirme avoir identifié un espace dans lequel Claude, son modèle d’IA, « réfléchit » à des idées sans forcément les verbaliser. Les machines disposeraient-elles d’un espace de réflexion consciente, à l’instar des humains ? Entretien de décryptage avec Stanislas Dehaene, professeur au Collège de France, directeur scientifique et responsable de l’unité de recherche en neuroimagerie cognitive de NeuroSpin, centre de recherche pour l','Dans une étude publiée début juillet, l’entreprise américaine Anthropic affirme avoir identifié un espace dans lequel Claude, son modèle d’IA, « réfléchit » à des idées sans forcément les verbaliser. Les machines disposeraient-elles d’un espace de réflexion consciente, à l’instar des humains ? Entretien de décryptage avec Stanislas Dehaene, professeur au Collège de France, directeur scientifique et responsable de l’unité de recherche en neuroimagerie cognitive de NeuroSpin, centre de recherche pour l',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.cea.fr/presse/Pages/actualites-communiques/ntic/modeles-langage-ont-ils-conscience.aspx',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','e50a66d23cceb628e0713b2a4d5648695acb531d6e6efe67bcf551afc28f6be9','68bc9049962a25fbe0829b4067ae3270a107b35eeaa445755091ab1f9d68aa63',1,1,1,1 FROM sources WHERE root_url='https://www.cea.fr/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-6B99124C93E3C6E262AC','research',NULL,'Europe: “Basic research should be central to the next Framework Programme” | CNRS','https://www.cnrs.fr/en/update/europe-basic-research-should-be-central-next-framework-programme',NULL,'CNRS','Direction de la communication','France','Europe','public_research','2024-07-17T12:00:00Z',NULL,'2026-10-03T22:48:42.271Z','institutional_primary','fr','As the final phase of strategic programming draws near for Horizon Europe, the framework programme for research and innovation, the European Commission has begun preparing its successor FP10 (10th Framework Programme), which will take effect in 2027. The CNRS is actively contributing to this future programme, emphasising basic research, European attractiveness, mobility, and collaborative research at more preliminary technological stages. An in-depth look with Antoine Petit, the CNRS Chairman & CEO.','As the final phase of strategic programming draws near for Horizon Europe, the framework programme for research and innovation, the European Commission has begun preparing its successor FP10 (10th Framework Programme), which will take effect in 2027. The CNRS is actively contributing to this future programme, emphasising basic research, European attractiveness, mobility, and collaborative research at more preliminary technological stages. An in-depth look with Antoine Petit, the