INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-62547FF48CE6E1F5CAC7','research',NULL,'The G6 calls for renewed ambition to drive the next European Framework Programme for Research and Innovation | CNRS','https://www.cnrs.fr/en/update/g6-calls-renewed-ambition-drive-next-european-framework-programme-research-and-innovation',NULL,'CNRS','Direction de la communication','France','Europe','public_research','2024-12-18T12:00:00Z',NULL,'2026-10-03T22:48:42.137Z','institutional_primary','fr','The G6 network made up of the six main European research organisations - CNR (Italy), CNRS (France), CSIC (Spain), Helmholtz Association, Leibniz Association and Max Planck Society (Germany) – and representing 135,000 employees, has published a statement calling for a shared vision for the upcoming Framework Programme, FP10.','The G6 network made up of the six main European research organisations - CNR (Italy), CNRS (France), CSIC (Spain), Helmholtz Association, Leibniz Association and Max Planck Society (Germany) – and representing 135,000 employees, has published a statement calling for a shared vision for the upcoming Framework Programme, FP10.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.cnrs.fr/en/update/g6-calls-renewed-ambition-drive-next-european-framework-programme-research-and-innovation',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anon