INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-3F9FEE29EB39D13E4610','research',NULL,'Accès aux documents administratifs | Inria','https://www.inria.fr/fr/acces-documents-administratifs',NULL,'Inria',NULL,'France','Europe','public_research',NULL,NULL,'2026-10-03T22:49:41.743Z','institutional_primary','fr','En vertu de l’Article L. 330-1 du code des relations entre le public et l’administration, le Président-directeur général d’Inria a désigné une personne responsable de l’accès aux documents administratifs et des questions relatives à la réutilisation des informations publiques (PRADA) :','En vertu de l’Article L. 330-1 du code des relations entre le public et l’administration, le Président-directeur général d’Inria a désigné une personne responsable de l’accès aux documents administratifs et des questions relatives à la réutilisation des informations publiques (PRADA) :',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.inria.fr/fr/acces-documents-administratifs',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','368325f92f020fafad847c1cd62c86c10d523572b8c8f35066a4539b430c1905','3f9fee29eb39d13e4610b7ff5ec8171286b1b44e6aac1710a86dbcd18f4e901b',1,1,1,1 FROM sources WHERE root_url='https://www.inria.fr/' ON CONFLICT(canonical_hash) DO UPDATE SE