INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-98EC6E6E76CF81BE8C00','science',NULL,'Health Inequality Monitor','https://www.who.int/data/inequality-monitor',NULL,'World Health Organization',NULL,'International','International','international_organization',NULL,NULL,'2026-10-03T22:48:39.809Z','institutional_primary','multi','Health equity is the absence of unfair, avoidable or remediable differences in health among population groups, defined by social, economic, demographic or geographic characteristics. Health inequalities are measurable differences in health across population subgroups. Monitoring health inequalities provides evidence on who is being left behind and informs health policies, programmes and practices that aim to close existing gaps and achieve health equity.','Health equity is the absence of unfair, avoidable or remediable differences in health among population groups, defined by social, economic, demographic or geographic characteristics. Health inequalities are measurable differences in health across population subgroups. Monitoring health inequalities provides evidence on who is being left behind and informs health policies, programmes and practices that aim to close existing gaps and achieve health equity.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.who.int/data/inequality-monitor',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','a238373d02cfcea40183437fc47ff59dca5704d98044fe49dc505d1072afd935','98ec6e6e76cf81be8c00a70817fde344fbddd1d8d686c1d8bff8eda4db970ce3',1,1,1,1 FROM sources WHERE root_url='https://www.who.int/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
