INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-E24188D5ECC4A11FD2A5','science',NULL,'WHO General Programme of Work','https://www.who.int/about/general-programme-of-work',NULL,'World Health Organization',NULL,'International','International','international_organization',NULL,NULL,'2026-10-03T22:48:39.788Z','institutional_primary','multi','WHO’s General Programme of Work (GPW) is a strategic document that sets a high-level roadmap and agenda for global health and identifies WHO’s priorities and strategic direction for a specified period. It also provides a framework for resource allocation and decision-making.','WHO’s General Programme of Work (GPW) is a strategic document that sets a high-level roadmap and agenda for global health and identifies WHO’s priorities and strategic direction for a specified period. It also provides a framework for resource allocation and decision-making.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.who.int/about/general-programme-of-work',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','5b7cbc1754a0231e8aff3862987c31f9a4f0b5a546cf56279cf4df8bcd39212a','e24188d5ecc4a11fd2a5adcff90106ca1ded2e4f533e50126864fa14e22309f5',1,1,1,1 FROM sources WHERE root_url='https://www.who.int/' ON CONFLICT(canonical_hash) DO UPDA