INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-213A5BC88430C0E5B361','research',NULL,'Bioenergy technology innovation - National Research Council Canada','https://nrc.canada.ca/en/research-development/nrc-facilities/bioenergy-technology-innovation',NULL,'National Research Council Canada',NULL,'Canada','North America','official_research_institution',NULL,NULL,'2026-10-03T22:51:39.265Z','institutional_primary','en','Let the NRC help you solve your biofuel combustion challenges for gas turbines. Our research facilities will help you develop the next generation of technologies for enhancing fuel flexibility, lowering emissions and improving operability, using an extensive range of test methods and equipment for fuel atomization and combustion. Take a virtual tour of the gas turbine research facilities to see how they could help your organization.','Let the NRC help you solve your biofuel combustion challenges for gas turbines. Our research facilities will help you develop the next generation of technologies for enhancing fuel flexibility, lowering emissions and improving operability, using an extensive range of test methods and equipment for fuel atomization and combustion. Take a virtual tour of the gas turbine research facilities to see how they could help your organization.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://nrc.canada.ca/en/research-develop