INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-B8D0C3EC9D0162A2C970','research',NULL,'Advanced material removal technologies - National Research Council Canada','https://nrc.canada.ca/en/research-development/nrc-facilities/advanced-material-removal-technologies',NULL,'NRC facilities',NULL,'Canada','North America','official_research_institution',NULL,NULL,'2026-10-03T22:52:11.522Z','institutional_primary','en','NRC&#039;s material removal experts develop high-performance, high-speed machining technologies to reduce costs and improve productivity in machining parts for the aerospace industry. Technologies currently under investigation include super-abrasive grinding, laser and vibration-assisted machining, dry machining, and machining under minimum quantity lubrication. Investigations are also carried out to enhance machine tool accuracy and cutting tool performance, and to optimize machining processes using simulation and modeling tools.','NRC&#039;s material removal experts develop high-performance, high-speed machining technologies to reduce costs and improve productivity in machining parts for the aerospace industry. Technologies currently under investigation include super-abrasive grinding, laser and vibration-assisted machining, dry machining, and machining under minimum quantity lubrication. Investigations are also carried out to enhance machine tool accuracy and cutting tool performance, and to optimize machining processes using simulation and modeling tools.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://nrc.canada.ca/en/research-development/nrc-facilities/advanced-material-removal-technologies',NULL,4,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','c6d2886ea783cc3dbf4311ef0702b65186c0dca7170718f30f9ead319ab3ce24','b8d0c3ec9d0162a2c970406a3aa35b6806833228c56e99eeec53756cf7b4466d',1,1,1,1 FROM sources WHERE root_url='https://nrc.canada.ca/en/research-development/nrc-facilities' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
