INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-8A75C074AD3F5DDD729E','research',NULL,'Digital inclusion programs for Canadians','https://ised-isde.canada.ca/site/ised/en/digital-inclusion-programs-canadians',NULL,'Seizing Canada''s Moment: Moving Forward in Science, Technology and Innovation (2014)',NULL,'Canada','North America','official_research_institution','2025-07-14',NULL,'2026-10-03T22:52:12.800Z','institutional_primary','en','Access to technology and solid digital skills are essential in today’s connected world. The Government of Canada is helping bridge the digital divide with programs that offer crucial digital and Artificial Intelligence (AI) skills training in emerging fields to youth, access to refurbished computer devices and low-cost internet. By improving access to the internet and providing digital and AI training, these initiatives help Canadians thrive in daily life and help youth prepare for the jobs of tomorrow.','Access to technology and solid digital skills are essential in today’s connected world. The Government of Canada is helping bridge the digital divide with programs that offer crucial digital and Artificial Intelligence (AI) skills training in emerging fields to youth, access to refurbished computer devices and low-cost internet. By improving access to the internet and providing digital and AI training, these initiatives help Canadians thrive in daily life and help youth prepare for the jobs of tomorrow.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://ised-isde.canada.ca/site/ised/en/digital-inclusion-programs-canadians',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','fb93f74db9f170c041b0a7b93ae14d5a1240cb30461987848056b8ea20a58140','8a75c074ad3f5ddd729e210b6b4856e37bc63d55c2bf88ab788c3e2668afd23c',1,1,1,1 FROM sources WHERE root_url='https://www.ic.gc.ca/eic/site/icgc.nsf/eng/h_07472.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
