INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-500ABE2DB4EDCD9973CA','research',NULL,'1.1 Introduction','https://tc.canada.ca/fr/aviation/services-aeriens-commerciaux/programme-pilote-verificateur-agree-pva-programme-avance-qualification-paq/document-elaboration-mise-oeuvre-programme-avance-qualification-paq/11-introduction',NULL,'Transport Canada',NULL,'Canada','North America','official_research_institution','2015-05-21',NULL,'2026-10-03T22:52:14.186Z','institutional_primary','en','Ce document fournit des lignes directrices pour obtenir l’autorisation d’un programme avancé de qualification (PAQ). Un PAQ est une méthode alternative de formation, d’évaluation, de qualification et de certification qui doit assurer la compétence des pilotes, des membres d’équipage de conduite, des instructeurs et des évaluateurs soumis aux exigences de formation et d’évaluation formulées dans les sous-parties 702, 703, 704 et 705 du Règlement de l’aviation canadien (RAC).','Ce document fournit des lignes directrices pour obtenir l’autorisation d’un programme avancé de qualification (PAQ). Un PAQ est une méthode alternative de formation, d’évaluation, de qualification et de certification qui doit assurer la compétence des pilotes, des membres d’équipage de conduite, des instructeurs et des évaluateurs soumis aux exigences de formation et d’évaluation formulées dans les sous-parties 702, 703, 704 et 705 du Règlement de 