INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-9F81CD1ABC09497C20BC','research',NULL,'1.2 Aperçu d&#039;un PAQ','https://tc.canada.ca/fr/aviation/services-aeriens-commerciaux/programme-pilote-verificateur-agree-pva-programme-avance-qualification-paq/document-elaboration-mise-oeuvre-programme-avance-qualification-paq/12-apercu-paq',NULL,'Transport Canada',NULL,'Canada','North America','official_research_institution','2012-03-02',NULL,'2026-10-03T22:52:14.261Z','institutional_primary','en','Le PAQ regroupe un certain nombre de caractéristiques de formation et d’évaluation conçues pour améliorer le rendement des programmes de formation traditionnels. Un PAQ est un système de formation basé sur les compétences, méthodiquement élaboré, sans cesse mis à jour, et validé par l’expérience. Un PAQ permet à un exploitant aérien l’élaboration, la mise en œuvre, l’évaluation et la gestion systématiques d’un programme de formation autocorrectif.','Le PAQ regroupe un certain nombre de caractéristiques de formation et d’évaluation conçues pour améliorer le rendement des programmes de formation traditionnels. Un PAQ est un système de formation basé sur les compétences, méthodiquement élaboré, sans cesse mis à jour, et validé par l’expérience. Un PAQ permet à un exploitant aérien l’élaboration, la mise en œuvre, l’évaluation et la gestion systématiques d’un programme de formation autocorrectif.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://tc.canada.ca/fr/aviation/services-aeriens-commerciaux/programme-pilote-verificateur-agree-pva-programme-avance-qualification-paq/document-elaboration-mise-oeuvre-programme-avance-qualification-paq/12-apercu-paq',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','8b8801e5cbef855e6040d7c1423ecd1bc48af706bc60f44746c5e240ffde8185','9f81cd1abc09497c20bc0990233712d1082699e968f6e9f521c31833ea410154',1,1,1,1 FROM sources WHERE root_url='https://www.canada.ca/en/transport-canada.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-8FA88D969FA5EBB76575','research',NULL,'2.1 Introduction','https://tc.canada.ca/fr/aviation/services-aeriens-commerciaux/programme-pilote-verificateur-agree-pva-programme-avance-qualification-paq/document-elaboration-mise-oeuvre-programme-avance-qualification-paq/21-introduction',NULL,'Transport Canada',NULL,'Canada','North America','official_research_institution','2010-10-19',NULL,'2026-10-03T22:52:14.255Z','institutional_primary','en','Le processus d’élaboration et de mise en œuvre d’un PAQ comporte cinq phases. Ce processus s’appuie sur une conception modulaire qui fournit un programme comprenant des cursus bien documentés, un exposé raisonné et une méthodologie d’élaboration. Ce processus normalisé d’élaboration, avec ses exigences en matière de documentation, permet au candidat PAQ de créer un programme de formation et d’évaluation basé sur des besoins analysés et justifiables. La documentation fournie par les cinq phases du processus servira ensuite de base réglementaire pour promulguer les programmes de formation et d’évaluation créés en vue d’un PAQ.','Le processus d’élaboration et de mise en œuvre d’un PAQ comporte cinq phases. Ce processus s’appuie sur une conception modulaire qui fournit un programme comprenant des cursus bien documentés, un exposé raisonné et une méthodologie d’élaboration. Ce processus normalisé d’élaboration, avec ses exigences en matière de documentation, permet au candidat PAQ de créer un programme de formation et d’évaluation basé sur des besoins analysés et justifiables. La documentation fournie par les cinq phases du processus servira ensuite de base réglementaire pour promulguer les programmes de formation et d’évaluation créés en vue d’un PAQ.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://tc.canada.ca/fr/aviation/services-aeriens-commerciaux/programme-pilote-verificateur-agree-pva-programme-avance-qualification-paq/document-elaboration-mise-oeuvre-programme-avance-qualification-paq/21-introduction',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','6021dff3ef5548cea6d2672e08ee10b39cfe8ee6b3dcaf099804fe8b5ed1a527','8fa88d969fa5ebb76575412eb6d36d9733f82c8f1ef57d903f08de4bad6c388b',1,1,1,1 FROM sources WHERE root_url='https://www.canada.ca/en/transport-canada.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-956FF585FEF8C94CB4C7','research',NULL,'2.2 Phase I – Demande','https://tc.canada.ca/fr/aviation/services-aeriens-commerciaux/programme-pilote-verificateur-agree-pva-programme-avance-qualification-paq/document-elaboration-mise-oeuvre-programme-avance-qualification-paq/22-phase-i-demande',NULL,'Transport Canada',NULL,'Canada','North America','official_research_institution','2010-10-22',NULL,'2026-10-03T22:52:14.259Z','institutional_primary','en','Le candidat désireux d’établir un PAQ doit commencer par envoyer une lettre à l’Inspecteur principal de l’exploitation (IPE) pour lui notifier son intention. Dans sa lettre de réponse, Transports Canada demandera à l’exploitant d’organiser une réunion avec des représentants de son département de la formation. La réunion comprendra l’IPE, un représentant de la Direction des opérations nationales ou d’une division régionale affectée à la surveillance opérationnelle (selon le cas), un expert des flottes aériennes en question (EM), un instructeur (selon le cas) et l’exploitant aérien en personne.','Le candidat désireux d’établir un PAQ doit commencer par envoyer une lettre à l’Inspecteur principal de l’exploitation (IPE) pour lui notifier son intention. Dans sa lettre de réponse, Transports Canada demandera à l’exploitant d’organiser une réunion avec des représentants de son département de la formation. La réunion comprendra l’IPE, un représentant de la Direction des opérations nationales ou d’une division régionale affectée à la surveillance opérationnelle (selon le cas), un expert des flottes aériennes en question (EM), un instructeur (selon le cas) et l’exploitant aérien en personne.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://tc.canada.ca/fr/aviation/services-aeriens-commerciaux/programme-pilote-verificateur-agree-pva-programme-avance-qualification-paq/document-elaboration-mise-oeuvre-programme-avance-qualification-paq/22-phase-i-demande',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','b37b25df753fa20e78e3713c41b6fa4516afb34cdbd3555ac2480b5970b7ff63','956ff585fef8c94cb4c787dee52d1f6db4e401305bd80110b7a1392d53ae3383',1,1,1,1 FROM sources WHERE root_url='https://www.canada.ca/en/transport-canada.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
