INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-69BABD26F6A1787B8171','research',NULL,'2.7 Document and Reporting Requirements','https://tc.canada.ca/en/aviation/commercial-air-services/approved-check-pilot-acp-advanced-qualification-program-aqp/development-implementation-advanced-qualification-program-aqp/27-document-reporting-requirements',NULL,'Transport Canada',NULL,'Canada','North America','official_research_institution','2010-10-20',NULL,'2026-10-03T22:52:14.180Z','institutional_primary','en','The approved AQP documentation establishes the applicant’s regulatory requirements for the particular training program. This fact makes it imperative that the applicant develops a document structure that is organized and standardized. The structure must ensure that the information contained within the AQP documents will be used and translated down to the lowest level of training guidance. It must allow the applicant’s entire organization to easily access and use the contents. Transport Canada has established a list of the minimum documentation required for AQP. The applicant may want to develop additional materials in support of their AQP.','The approved AQP documentation establishes the applicant’s regulatory requirements for the particular training program. This fact makes it imperative that the applicant develops a document structure that is organized and standardized. The structure must ensure that the information contained within the AQP documents will be used and translated down to the lowest level of training guidance. It must allow the applicant’s entire organization to easily access and use the contents. Transport Canada has established a list of the minimum documentation required for AQP. The applicant may want to develop additional materials in support of their AQP.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://tc.canada.ca/en/aviation/commercial-air-services/approved-check-pilot-acp-advanced-qualification-program-aqp/development-implementation-advanced-qualification-program-aqp/27-document-reporting-requirements',NULL,3,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','24a5550591fc64c5da16dc4162bea3ee29800b589639c6dd104e9ea01ee5b4fc','69babd26f6a1787b8171c76e00345597f278109a1148c4eada2e7b02a1e3255c',1,1,1,1 FROM sources WHERE root_url='https://www.canada.ca/en/transport-canada.html' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
