INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-E551DDB062B6140FD1CC','research',NULL,'Machine Learning Accelerated Materials Discovery Center | Ames Laboratory','https://www.ameslab.gov/machine-learning-accelerated-materials-discovery-center',NULL,'Learn More',NULL,'United States','North America','official_research_institution',NULL,NULL,'2026-10-03T22:50:09.322Z','institutional_primary','en','This homepage provides an overview of the Machine Learning Accelerated Materials Discovery Center. For current project progress, publications, software and data resources, and project updates, please visit the MLAMD project website.Accelerating the discovery and design of advanced functional materials using AI/ML and exascale computingThrough this project, we will develop a series of exascale-capable computational codes and workflows that integrate materials theories and methods with Artificial Intelligence/Machine Learning (AI/ML) tools and materials databases, as well as the software stack developed through the Exascale Computing Program (ECP). The goal is to dramatically increase the speed of predicting new materials in new composition-structure-property spaces and identifying synthetic pathways for new functional materials. We will produce AI/ML integrated and validated open-source, ','This homepage provides an overview of the Machine Learning Accelerated Materials Discovery Center. For current project progress, publications, software and data resources, and project updates, please visit the MLAMD project website.Accelerating the discovery and design of advanced functional materials using AI/ML and exascale computingThrough this project, we will develop a series of exascale-capable computational codes and workflows that integrate materials theories and methods with Artificial Intelligence/Machine Learning (AI/ML) tools and materials databases, as well as the software stack developed through the Exascale Computing Program (ECP). The goal is to dramatically increase the speed of predicting new materials in new composition-structure-property spaces and identifying synthetic pathways for new functional materials. We will produce AI/ML integrated and validated open-source, ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ameslab.gov/machine-learning-accelerated-materials-discovery-center',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','1c58deafa68232fe10fe689a0f1e055aa0403f18356d1e9fe339d8ee72164119','e551ddb062b6140fd1cccfb39dc50aa37218a8993f3043edcd1ddcaa4401047b',1,1,1,1 FROM sources WHERE root_url='https://www.ameslab.gov/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
