INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-491A4045D70C7E3DEF9A','research',NULL,'Science &#038; Technology Facilities &#8211; Research','https://www.sandia.gov/research/facilities/',NULL,'Learn More',NULL,'United States','North America','official_research_institution',NULL,NULL,'2026-10-03T22:51:04.361Z','institutional_primary','en','Sandia National Laboratories, one of the largest Department of Energy (DOE) research facilities, utilizes specialized buildings and equipment to conduct world-class research and effectively meet unique program requirements. The facilities tagged as a Technology Deployment Center (TDC) can be used by outside researchers; see this Work With Sandia page for more information on collaboration opportunities.','Sandia National Laboratories, one of the largest Department of Energy (DOE) research facilities, utilizes specialized buildings and equipment to conduct world-class research and effectively meet unique program requirements. The facilities tagged as a Technology Deployment Center (TDC) can be used by outside researchers; see this Work With Sandia page for more information on collaboration opportunities.',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.sandia.gov/research/facilities/',NULL,2,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à un