INSERT INTO documents(source_id,corpus,internal_id,topic,subtopic,exact_title,canonical_url,pdf_url,institution,author,country,geographic_area,organization_type,publication_date,updated_date,consulted_at,source_kind,language,factual_summary,essential_information,keywords,technology,performance,lock_concerned,maturity_trl,doi,official_identifier,licence,access_status,primary_secondary,peer_reviewed,quantitative_data,unit,evidence_location,contradiction,relevance_score,evidence_level,verification_level,http_status,control_comment,content_sha256,canonical_hash,official,public_access,free_access,active) SELECT id,'A','DOC-A68BF246665320E004E4','research',NULL,'Simulation, Modeling and Decision Science | Ames Laboratory','https://www.ameslab.gov/smds',NULL,'Learn More',NULL,'United States','North America','official_research_institution',NULL,NULL,'2026-10-03T22:50:09.441Z','institutional_primary','en','Changes to the U.S. electricity industry are forcing a paradigm shift in how the nation’s generating assets are operated. Power plants, originally optimized as baseload resources, are being increasingly relied upon as load-following resources to support electricity generated from intermittent renewable capacity. This fundamental change to the operating and economic environment in which large-scale power plants function will persist beyond the next decade, and will require significant changes in operations, controls, and maintenance practices.Our research on power plant monitoring and controls is focused on the near-term challenge of developing low-cost, easily implemented tools that aid in optimizing cycling operations by maintaining plant performance and system durability for industrial power systems. Ames National Laboratory&#039;s Division of Simulation, Modeling and Decision Science ','Changes to the U.S. electricity industry are forcing a paradigm shift in how the nation’s generating assets are operated. Power plants, originally optimized as baseload resources, are being increasingly relied upon as load-following resources to support electricity generated from intermittent renewable capacity. This fundamental change to the operating and economic environment in which large-scale power plants function will persist beyond the next decade, and will require significant changes in operations, controls, and maintenance practices.Our research on power plant monitoring and controls is focused on the near-term challenge of developing low-cost, easily implemented tools that aid in optimizing cycling operations by maintaining plant performance and system durability for industrial power systems. Ames National Laboratory&#039;s Division of Simulation, Modeling and Decision Science ',NULL,NULL,NULL,NULL,NULL,NULL,NULL,NULL,'free','primary','not_applicable',NULL,NULL,'https://www.ameslab.gov/smds',NULL,1,'B','V2',200,'V2: institution certifiée 3/3, URL ouverte anonymement, titre et contenu vérifiés automatiquement. V3 réservé à une validation plus forte.','dc5820c4e67ce87097c8c2031f1f9c13e8c9597f31be22d8f8060add0a2a745f','a68bf246665320e004e4a47898f3e42fa195f99ec180336ccabfe44b32afe130',1,1,1,1 FROM sources WHERE root_url='https://www.ameslab.gov/' ON CONFLICT(canonical_hash) DO UPDATE SET consulted_at=excluded.consulted_at,http_status=excluded.http_status,content_sha256=excluded.content_sha256,exact_title=excluded.exact_title,factual_summary=excluded.factual_summary,active=1;
